const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const ShoppingCart = require('../src/cart');

describe('ShoppingCart', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  describe('constructor', () => {
    it('starts empty with no discount', () => {
      assert.deepEqual(cart.items, []);
      assert.equal(cart.discount, 0);
      assert.equal(cart.getItemCount(), 0);
    });
  });

  describe('addItem', () => {
    it('adds a new item', () => {
      cart.addItem('apple', 1.5, 2);
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1.5, quantity: 2 }]);
      assert.equal(cart.getItemCount(), 1);
    });

    it('adds multiple distinct items', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 3);
      assert.equal(cart.getItemCount(), 2);
    });

    it('merges quantity when the same item is added again', () => {
      cart.addItem('apple', 1, 2);
      cart.addItem('apple', 1, 3);
      assert.equal(cart.getItemCount(), 1);
      assert.equal(cart.items[0].quantity, 5);
    });

    it('allows a free (price 0) item', () => {
      cart.addItem('sticker', 0, 1);
      assert.equal(cart.getItemCount(), 1);
      assert.equal(cart.getTotal(), 0);
    });

    // Regression: Bug 1 — negative price was accepted
    it('rejects a negative price', () => {
      assert.throws(() => cart.addItem('apple', -1, 1), RangeError);
      assert.equal(cart.getItemCount(), 0);
    });

    // Regression: Bug 1 — negative quantity was accepted
    it('rejects a negative quantity', () => {
      assert.throws(() => cart.addItem('apple', 1, -1), RangeError);
      assert.equal(cart.getItemCount(), 0);
    });

    // Regression: Bug 1 — a negative quantity on an existing item silently reduced it
    it('rejects a negative quantity for an item already in the cart', () => {
      cart.addItem('apple', 1, 5);
      assert.throws(() => cart.addItem('apple', 1, -3), RangeError);
      assert.equal(cart.items[0].quantity, 5);
    });

    it('rejects a zero quantity', () => {
      assert.throws(() => cart.addItem('apple', 1, 0), RangeError);
    });

    it('rejects a fractional quantity', () => {
      assert.throws(() => cart.addItem('apple', 1, 1.5), RangeError);
    });

    it('rejects non-numeric, NaN, and infinite values', () => {
      assert.throws(() => cart.addItem('apple', '1', 1), RangeError);
      assert.throws(() => cart.addItem('apple', NaN, 1), RangeError);
      assert.throws(() => cart.addItem('apple', Infinity, 1), RangeError);
      assert.throws(() => cart.addItem('apple', 1, '2'), RangeError);
      assert.throws(() => cart.addItem('apple', 1, NaN), RangeError);
      assert.throws(() => cart.addItem('apple', 1), RangeError);
      assert.equal(cart.getItemCount(), 0);
    });
  });

  describe('removeItem', () => {
    // Regression: Bug 2 — `=` kept every item (and renamed them all)
    it('removes only the named item', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 1);
      cart.addItem('cherry', 3, 1);

      cart.removeItem('banana');

      assert.deepEqual(
        cart.items.map(i => i.name),
        ['apple', 'cherry'],
      );
    });

    // Regression: Bug 2 — `=` overwrote the name of every remaining item
    it('does not mutate the names of remaining items', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 1);

      cart.removeItem('apple');

      assert.deepEqual(cart.items, [{ name: 'banana', price: 2, quantity: 1 }]);
    });

    it('returns true when an item is removed', () => {
      cart.addItem('apple', 1, 1);
      assert.equal(cart.removeItem('apple'), true);
      assert.equal(cart.getItemCount(), 0);
    });

    // Regression: Bug 2 — missing item was not handled
    it('returns false and leaves the cart untouched when the item is missing', () => {
      cart.addItem('apple', 1, 1);

      assert.equal(cart.removeItem('pear'), false);

      assert.deepEqual(cart.items, [{ name: 'apple', price: 1, quantity: 1 }]);
    });

    it('returns false when removing from an empty cart', () => {
      assert.equal(cart.removeItem('apple'), false);
      assert.equal(cart.getItemCount(), 0);
    });

    it('updates the total after removal', () => {
      cart.addItem('apple', 1, 2);
      cart.addItem('banana', 5, 1);
      cart.removeItem('apple');
      assert.equal(cart.getTotal(), 5);
    });
  });

  describe('getTotal', () => {
    // Regression: Bug 3 — `<=` read past the end of the array and threw
    it('returns 0 for an empty cart', () => {
      assert.equal(cart.getTotal(), 0);
    });

    // Regression: Bug 3 — `<=` read past the end of the array and threw
    it('sums price * quantity across all items', () => {
      cart.addItem('apple', 2, 3);   // 6
      cart.addItem('banana', 5, 1);  // 5
      cart.addItem('cherry', 1, 4);  // 4
      assert.equal(cart.getTotal(), 15);
    });

    it('handles a single item', () => {
      cart.addItem('apple', 10, 1);
      assert.equal(cart.getTotal(), 10);
    });

    it('handles decimal prices', () => {
      cart.addItem('apple', 0.1, 3);
      cart.addItem('banana', 0.2, 1);
      assert.ok(Math.abs(cart.getTotal() - 0.5) < 1e-9);
    });

    // Regression: Bug 4 — discount was added to the total instead of subtracted
    it('subtracts the discount from the total', () => {
      cart.addItem('apple', 100, 1);
      cart.applyDiscount(10);
      assert.equal(cart.getTotal(), 90);
    });

    // Regression: Bug 4
    it('never returns more than the undiscounted total when a discount is set', () => {
      cart.addItem('apple', 40, 2);
      cart.addItem('banana', 20, 1);
      const before = cart.getTotal();
      cart.applyDiscount(25);
      assert.equal(before, 100);
      assert.equal(cart.getTotal(), 75);
    });

    it('returns the full total with a 0% discount', () => {
      cart.addItem('apple', 50, 2);
      cart.applyDiscount(0);
      assert.equal(cart.getTotal(), 100);
    });

    it('returns 0 with a 100% discount', () => {
      cart.addItem('apple', 50, 2);
      cart.applyDiscount(100);
      assert.equal(cart.getTotal(), 0);
    });

    it('applies the discount to items added after the discount was set', () => {
      cart.applyDiscount(50);
      cart.addItem('apple', 20, 1);
      assert.equal(cart.getTotal(), 10);
    });
  });

  describe('applyDiscount', () => {
    it('stores a valid discount', () => {
      cart.applyDiscount(15);
      assert.equal(cart.discount, 15);
    });

    it('accepts the boundary values 0 and 100', () => {
      cart.applyDiscount(0);
      assert.equal(cart.discount, 0);
      cart.applyDiscount(100);
      assert.equal(cart.discount, 100);
    });

    it('accepts a fractional percentage', () => {
      cart.addItem('apple', 200, 1);
      cart.applyDiscount(12.5);
      assert.equal(cart.getTotal(), 175);
    });

    it('replaces a previous discount rather than stacking', () => {
      cart.addItem('apple', 100, 1);
      cart.applyDiscount(10);
      cart.applyDiscount(20);
      assert.equal(cart.getTotal(), 80);
    });

    // Regression: Bug 5 — discounts over 100% were accepted
    it('rejects a discount greater than 100', () => {
      assert.throws(() => cart.applyDiscount(101), RangeError);
      assert.throws(() => cart.applyDiscount(150), RangeError);
    });

    // Regression: Bug 5 — negative discounts were accepted
    it('rejects a negative discount', () => {
      assert.throws(() => cart.applyDiscount(-1), RangeError);
    });

    it('rejects non-numeric, NaN, and infinite discounts', () => {
      assert.throws(() => cart.applyDiscount('10'), RangeError);
      assert.throws(() => cart.applyDiscount(NaN), RangeError);
      assert.throws(() => cart.applyDiscount(Infinity), RangeError);
      assert.throws(() => cart.applyDiscount(), RangeError);
    });

    // Regression: Bug 5 — an invalid discount must not overwrite the current one
    it('keeps the previous discount when an invalid one is rejected', () => {
      cart.addItem('apple', 100, 1);
      cart.applyDiscount(10);
      assert.throws(() => cart.applyDiscount(200), RangeError);
      assert.equal(cart.discount, 10);
      assert.equal(cart.getTotal(), 90);
    });
  });
});

